const escapeHtml = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const readingOrder = ['start','values','representation','selection','loops','functions','arrays','files','design','software-responsibility','networks','addressing','network-design','network-review','consolidation','exam-preparation'];
function lessonPage(ch){const order=ch.unit===4?['unit4-design','unit4-sql','unit4-project','unit4-analysis','unit4-controls','unit4-crypto','unit4-ethics','unit4-review','unit4-consolidation','unit4-exam']:ch.unit===3?['unit3-fluency','unit3-structures','unit3-search','unit3-sort','unit3-objects','unit3-inheritance','unit3-project','unit3-reliability','unit3-network-models','unit3-addressing','unit3-secure-networks','unit3-review','unit3-consolidation','unit3-exam']:ch.unit===2?['database-foundations','entities-relationships','normalisation','sql-basics','database-solution','security-threats','responsible-data','unit2-review','unit2-consolidation','unit2-exam']:readingOrder;const position=order.indexOf(ch.id);return `<article class="lesson"><p class="eyebrow">UNIT ${ch.unit||1} / WEEK ${ch.week} / CHAPTER ${position+1}</p><h1>${ch.title}</h1><p class="lede">${ch.intro}</p><span class="pill">${ch.badge||'PYTHON 3'}</span> <span class="pill">CLASSROOM DRAFT · REVIEW PENDING</span><div class="no-print" style="margin-top:20px"><button id="chapter-print">Print / save as PDF</button> ${ch.code?'<button id="chapter-download">Download example</button>':''}</div><h2>What you’ll learn</h2><div class="objectives"><ul>${ch.objectives.map(x=>`<li>${x}</li>`).join('')}</ul></div>${ch.sections.map(([title,html],i)=>`<section><h2>${i+1}. ${title}</h2>${html}</section>`).join('')}${ch.code?`<h2>Worked Python example</h2><p>Predict the result first, then run and modify the downloaded file in your Python environment.</p><pre><code>${escapeHtml(ch.code)}</code></pre>`:''}<h2>Practise and explain</h2>${ch.practice.map(([type,q,a])=>`<section class="practice"><p class="eyebrow">${type}</p><p>${q}</p><details><summary>Show explained answer</summary><p>${escapeHtml(a)}</p></details></section>`).join('')}<h2>Your practical task</h2><div class="card"><p>${ch.task}</p><details><summary>Show illustrative answer / example</summary>${ch.code?`<pre><code>${escapeHtml(ch.solution)}</code></pre><p>Compare the logic and tests, not just the spelling of variable names.</p>`:`<p>${escapeHtml(ch.solution)}</p>`}</details></div><h2>Check your understanding</h2><p>${ch.quiz.q}</p><div id="chapter-quiz">${ch.quiz.options.map((t,i)=>`<button class="quiz-option" data-choice="${i}">${escapeHtml(t)}</button>`).join(' ')}</div><p id="chapter-feedback" class="feedback" aria-live="polite"></p><h2>Chapter recap</h2><p>${ch.recap}</p><details><summary>Suggested classroom sequence</summary><ol>${ch.lessons.map(x=>`<li>${x}</li>`).join('')}</ol><p>${(ch.unit||1)===1&&ch.week===2?"Week 2 is shared by the values and representation chapters; their activities fit into four total lessons. ":""}This draft chapter provides learning activities and explained answers. It does not establish complete syllabus coverage.</p></details><p class="reference">Technical reference: <a href="${ch.reference}" target="_blank" rel="noopener">${ch.refTitle}</a>. Curriculum requirements: <a href="${source}" target="_blank" rel="noopener">SCSA Computer Science</a>.</p><nav class="chapter-nav no-print">${position>0?`<a href="#${order[position-1]}">← Previous chapter</a>`:'<a href="#contents">← Contents</a>'}${position<order.length-1?`<a href="#${order[position+1]}">Next chapter →</a>`:ch.next?`<a href="${ch.next}">Next planned chapter →</a>`:'<a href="#teaching">View teaching sequence →</a>'}</nav></article>`}
function downloadText(text,name){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function teachingPage(){const schedule=[['1','Your first Python program','Diagnose → model → trace → apply'],['2','Values, types and representation','Types/operators and base/character representation share four lessons'],['3','Making decisions with selection','Comparisons → Boolean logic → branches → boundary tests'],['4','Repeating work with loops','for → while → trace → independent task'],['5','Functions and scope','Define → call → return/scope → refactor'],['6','One-dimensional arrays','Load/display → total → min/max → edge tests'],['7','Text files and reliable input','Files → validation → combined task → practical assessment'],['8–10','Designing and testing solutions','Investigate → design → build/test → acceptance and evaluation'],['11','Network foundations','Protocols → layers → trace → explain'],['12','Addresses, devices and media','Addresses → masks → devices → media choices'],['13','Designing and protecting a network','Diagram → controls → performance → evaluate'],['14','Network scenarios and review','Retrieve → scenario → assess → feedback'],['15','Unit 1 consolidation','Diagnose → stations → transfer → revision plan'],['16','Unit 1 exam preparation','Attempt → mark → targeted practice → final checks']];return `<p class="eyebrow">TEACHING SEQUENCE / UNIT 1</p><h1>Programming into practice.</h1><p class="lede">Weeks 1–16: four lessons each week, with retrieval, feedback and ten project lessons built in.</p><table><tr><th>Week</th><th>Chapters</th><th>Lesson progression</th></tr>${schedule.map(row=>`<tr>${row.map(t=>`<td>${t}</td>`).join('')}</tr>`).join('')}</table><h2>Unit 2: modelling into SQL</h2><p>Semester week 1 uses four lessons: data and information → flat-file maintenance → DBMS and related tables → independent workbook and feedback. Use the equipment-loan scenario and synthetic records.</p><p>Week 2 uses four lessons: entities and identifiers → key/reference checks → crow’s-foot relationships → data dictionary and feedback.</p><p>Week 3 uses four lessons: anomalies/1NF → partial dependencies/2NF → transitive dependencies/3NF → independent transfer and feedback.</p><p>Week 4 uses four lessons: open/query → filters → Boolean logic and ordering → independent reports and feedback.</p><p>Weeks 5–7: four lessons each week for joins/aggregates → controlled changes/testing → project launch. Ten further project workshops occupy two lessons per week in weeks 8–12, alongside security instruction.</p><p>Weeks 8–11: two security lessons plus two project workshops each week. CIA/AAA → threats/controls → authentication/encryption → classroom ciphers. Week 12: two privacy/ethical-testing lessons and two project evaluation/demonstration lessons.</p><p>Weeks 13–14: integrated review and controlled practice; week 15: consolidation; week 16: exam preparation; weeks 17–18 are reserved for exams. Total 64 teaching lessons, with 14 project lessons already embedded.</p><p><a href="#unit2-coverage">Unit 2 audit</a> · <a href="#unit2-review">Integrated review</a> · <a href="#unit2-consolidation">Consolidation</a> · <a href="#unit2-exam">Exam preparation</a></p><p><a href="#responsible-data">Read Responsible data use →</a></p><p><a href="#security-threats">Read Threats and protective measures →</a></p><p><a href="#database-solution">Read Building a database solution →</a></p><p><a href="#sql-basics">Read Getting started with SQL →</a> · <a href="#normalisation">Read normalisation →</a></p><p><a href="#database-foundations">Read database foundations →</a> · <a href="#entities-relationships">Read modelling →</a></p><h2>Unit 3: rebuild fluency</h2><p>Week 1 uses four lessons: diagnose/trace → repair/test → compare development/change requirements → version/restore evidence. <a href="#unit3-fluency">Read the opening chapter</a>. Year 12 reference: <a href="https://senior-secondary.scsa.wa.edu.au/__data/assets/pdf_file/0013/1211323/_Computer-Science-ATAR-Year-12-Syllabus-for-teaching-from-January-2026.PDF">2026 syllabus</a>.</p><p>Unit 3 week 2 uses four lessons: 2D grids/traversal → dictionaries → mutation/rebinding/copying → booking report and testing. <a href="#unit3-structures">Read Advanced data structures</a>. The practical is embedded within these four lessons.</p><p>Unit 3 week 3: linear search/contracts → binary search/tracing → implementation and boundary tests → probe-count growth and algorithm choice. <a href="#unit3-search">Read Searching</a>. Four lessons; week 4 proceeds to sorting before objects in weeks 5–6.</p><p>Unit 3 week 4: bubble passes/early exit → insertion/shifts → selection/testing → growth, stability and scenario choice. <a href="#unit3-sort">Read Sorting algorithms</a>. Four lessons; objects and classes follow in week 5.</p><p>Unit 3 week 5: design/instantiate → methods and state → encapsulation/aliases/refactoring → class tests and object search/report. <a href="#unit3-objects">Read Objects and classes</a>. Four lessons; inheritance and polymorphism follow in week 6.</p><p>Unit 3 week 6: hierarchy/super → overriding/polymorphism → guided implementation/testing → controlled practical. <a href="#unit3-inheritance">Read Extending object-oriented design</a>. Four lessons; the practical replaces normal lesson 4 practice. Week 7 launches the software project.</p><p>Unit 3 project: four lessons in week 7, two workshops in each of weeks 8–9 and four lessons in week 10. <a href="#unit3-project">Read Developing a software solution</a>. Twelve project lessons are already embedded; instruction in reliability and maintenance remains separate in weeks 8–9.</p><p>Unit 3 weeks 8–9 explicit lessons: week 8 lessons 1–2 testing/debugging and acceptance/load; week 9 lessons 1–2 code review/regression/version recovery and developer responsibilities. <a href="#unit3-reliability">Read Reliable software</a>. Two project workshops each week remain separate; week 10 project completion is unchanged.</p><p>Unit 3 week 11: OSI/TCP-IP and encapsulation → switching/routing/address roles → TCP/UDP and byte traces → sizing/scenarios/feedback. <a href="#unit3-network-models">Read Network models and protocols</a>. Four lessons; week 12 proceeds to addressing/subnetting and week 13 to network design.</p><p>Unit 3 week 12: address scope/prefixes → subnet/gateway calculations → variable-length plan → IPv6 and independent diagnosis. <a href="#unit3-addressing">Read Addressing and subnetting</a>. Four lessons; week 13 develops network design and security choices.</p><p>Unit 3 week 13: requirements/Cisco diagram conventions → segmentation/policy → capacity → troubleshooting and evaluation. <a href="#unit3-secure-networks">Read Designing secure networks</a>. Four lessons with embedded practical work; integrated review follows in week 14.</p><p>Unit 3 week 14: diagnostic/programming correction → network case → controlled formative practice → feedback/fresh transfer. <a href="#unit3-review">Read Unit 3 integrated review</a>. Four lessons; targeted consolidation follows in week 15.</p><p>Unit 3 week 15: evidence/priorities → two targeted stations → fresh mixed transfer → delayed retry/revision plan. <a href="#unit3-consolidation">Read Unit 3 consolidation</a>. Four lessons; week 16 prepares for exams.</p><p>Unit 3 week 16: commands/pacing → original timed sample → marking/correction → fresh retries/readiness. <a href="#unit3-exam">Read Unit 3 exam preparation</a>. Four lessons; weeks 17–18 are reserved for exams. Coverage audit and practical evidence remain pending.</p><h2>Unit 4: refine database design</h2><p>Week 1: dependencies/anomalies → six-table relationships/notation → dictionary/schema integrity → independent design transfer. <a href="#unit4-design">Read Refining relational database designs</a>. Four lessons; advanced SQL follows.</p><p>Unit 4 weeks 2–3: four-table joins/aliases → grouping → zero-row counts → calculations/concatenation → composite-key/NULL/filtering → report debugging/transfer. <a href="#unit4-sql">Read Advanced SQL queries</a>. Eight lessons; database development follows.</p><p>Unit 4 week 4: controlled changes → import → transactions → recovery and testing. <a href="#unit4-project">Database project</a>: 16 workshops are embedded in week 5 (four), weeks 6–9 (two each) and week 10 (four). Security instruction is scheduled separately; no extra weeks are required.</p><p>Unit 4 week 6 security: CIA and AAA concepts → threat mechanisms → synthetic log and case analysis, including the limits of the evidence. <a href="#unit4-analysis">Read Cyber security analysis</a>. Two explicit lessons plus two separate database workshops; week 7 evaluates controls.</p><p>Unit 4 week 7 security: the purpose and limits of controls, including ordered rules → response testing and evaluation. <a href="#unit4-controls">Read Security controls and responses</a>. Two explicit lessons plus two project workshops; secure communication follows in week 8.</p><p>Unit 4 Week 8: key roles and historical ciphers → certificates and TLS. <a href="#unit4-crypto">Read Secure communication and cryptography</a>. Two security lessons plus two database project workshops; ethical and legal considerations follow in Week 9.</p><p>Unit 4 Week 9: privacy principles and breach cases → responsible data use and paper red/blue-team review. <a href="#unit4-ethics">Read Ethical and legal considerations</a>. Two security lessons plus two database workshops. Week 10 completes the project, then integrated review; Weeks 17–18 remain blocked for exams.</p><p>Unit 4 Weeks 11–12: eight integrated review lessons after project completion, including the existing theory-test slot, feedback and fresh transfer. <a href="#unit4-review">Read Unit 4 integrated review</a>. Weeks 13–14 consolidate the full course; Weeks 15–16 prepare for exams; Weeks 17–18 are reserved for exams.</p><p>Unit 4 Weeks 13–14: eight lessons for diagnostic, common clinics, two priority repairs, mixed transfer and delayed retries. <a href="#unit4-consolidation">Read Full-course consolidation</a>. Weeks 15–16 remain exam preparation; Weeks 17–18 are reserved for exams.</p><p>Unit 4 Weeks 15–16: eight exam-preparation lessons with two original timed samples, explained marking, fresh/later retries and readiness planning. <a href="#unit4-exam">Read Full-course exam preparation</a>. Weeks 17–18 are reserved for school exams; the external examination timetable is separate. <a href="#unit4-coverage">Unit 4 coverage audit</a> is available; content repairs and review/evidence remain pending.</p><h2>The rest of the Unit 1 semester</h2><p>Weeks 8–10: design, build and evaluate the club-order project. Weeks 11–14: networks and applied assessment. Weeks 15–16: consolidation and exam preparation. Weeks 17–18 are blocked for exams. The first seven weeks prepare the skills for the project; they do not introduce another major summative project.</p><p><a class="button" href="teaching-sequence.md" download>Download complete Units 1–4 outline</a></p><div class="notice">Chapters are ready for teacher review. The <a href="#audits">editorial coverage audits</a> map content across all four units; classroom evidence, symbol fidelity and independent review still need checking. Review the total teaching time against the notional 55 hours per unit: 64 lessons of 52 minutes provide approximately 55.5 hours, before any lost teaching time.</div>`}
function render(){const route=currentTextbookRoute();const ch=chapters.find(c=>c.id===route);if(ch){document.querySelector('main').innerHTML=lessonPage(ch)+footer;window.scrollTo(0,0);if(ch.code)document.querySelector('#chapter-download').onclick=()=>downloadText(ch.code,`${ch.id}_example.py`);document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{const correct=Number(b.dataset.choice)===ch.quiz.answer;document.querySelector('#chapter-feedback').textContent=(correct?'Correct. ':'Try again. ')+ch.quiz.explanation});document.title=ch.title+' | CS ATAR';}else if(route==='audits'){document.querySelector('main').innerHTML=auditHubPage()+footer;window.scrollTo(0,0);document.title='Coverage & audits | CS ATAR';}else if(route==='unit4-coverage'){document.querySelector('main').innerHTML=unit4CoveragePage()+footer;window.scrollTo(0,0);document.title='Unit 4 coverage audit | CS ATAR';}else if(route==='unit3-evidence'){document.querySelector('main').innerHTML=unit3EvidencePage()+footer;window.scrollTo(0,0);document.title='Unit 3 practical evidence | CS ATAR';}else if(route==='unit3-coverage'){document.querySelector('main').innerHTML=unit3CoveragePage()+footer;window.scrollTo(0,0);document.title='Unit 3 coverage audit | CS ATAR';}else if(route==='unit2-coverage'){document.querySelector('main').innerHTML=unit2CoveragePage()+footer;window.scrollTo(0,0);document.title='Unit 2 coverage audit | CS ATAR';}else if(route==='coverage'){document.querySelector('main').innerHTML=coveragePage()+footer;window.scrollTo(0,0);document.title='Unit 1 coverage audit | CS ATAR';}else if(route==='teaching'){document.querySelector('main').innerHTML=teachingPage()+footer;window.scrollTo(0,0);document.title='Teaching sequence | CS ATAR';}else{renderLegacy();document.title=(route==='selection'?'Making decisions with selection':route==='glossary'?'Glossary':'Computer Science ATAR')+' | Classroom Textbook';if(route==='selection'){const nav=document.createElement('nav');nav.className='chapter-nav no-print';nav.innerHTML='<a href="#representation">← Previous chapter</a><a href="#loops">Next chapter →</a>';document.querySelector('.lesson').append(nav);}}}
window.addEventListener('hashchange',render);render();
